 async backupRecoveryKey(){modal('Guardar clave de recuperación','<p>Conservá este archivo fuera de Railway, en un lugar privado. No lo compartas ni lo subas al repositorio del programa.</p>'+field('password','Contraseña actual del administrador','password','','required autocomplete="current-password"'),async v=>{const r=await api('admin/drive',{op:'recovery',password:v.password});download(JSON.stringify({format:'traza-recovery-key-v1',key:r.key},null,2),'Traza-clave-recuperacion.json','application/json')},'Descargar clave')},
