 async adminStock(){
	  const availableCompanies=adminCompanyId?admin.companies.filter(x=>x.id===adminCompanyId):admin.companies;if(!availableCompanies.length)throw Error('No hay empresas para ajustar.');let data;
	  for(const company of availableCompanies){const candidate=await api('admin/stock?companyId='+encodeURIComponent(company.id));if(candidate.lots.length){data=candidate;break}}
  if(!data)throw Error('Ninguna empresa tiene lotes para ajustar.');
  const lotOptions=lots=>lots.map(l=>({id:l.id,name:l.itemName+' · lote '+l.code+' · saldo '+num(l.remaining)+' '+l.unit}));
	  const fields=()=>{const first=data.lots[0];return select('companyId','Empresa',availableCompanies,data.company.id,false)+field('stockSearch','Buscar artículo o lote','search','','placeholder="Escribí parte del nombre o lote"')+select('lotId','Producto y lote a ajustar',lotOptions(data.lots),first?.id||'',false)+'<p id="stockAdjustmentCurrent" class="full muted"></p>'+dateField()+field('actualQty','Stock real contado','number',first?.remaining??'','min="0" step="any" required')+field('reason','Motivo del ajuste','text','','required maxlength="500"')};
	  modal('Ajustar productos en stock',fields(),async v=>api('admin/stock?companyId='+encodeURIComponent(v.companyId),{lotId:v.lotId,date:v.date,actualQty:Number(v.actualQty),reason:v.reason}),'Registrar ajuste');
	  const visibleLots=()=>{const q=searchText($('[name=stockSearch]').value);return data.lots.filter(l=>!q||searchText(l.itemName+' '+l.code).includes(q))};
	  const syncLot=()=>{const l=data.lots.find(x=>x.id===$('[name=lotId]').value);$('#stockAdjustmentCurrent').textContent=l?'Saldo registrado: '+num(l.remaining)+' '+l.unit+' · Estado: '+l.status+(l.expiry?' · Vence: '+l.expiry:''):'';$('[name=actualQty]').value=l?.remaining??''};
	  const drawLots=()=>{const found=visibleLots();$('[name=lotId]').innerHTML=lotOptions(found).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');syncLot();$('#formError').textContent=found.length?'':'No se encontraron productos o lotes con esa búsqueda.'};
	  $('[name=lotId]').onchange=syncLot;$('[name=stockSearch]').oninput=drawLots;$('[name=companyId]').onchange=async()=>{try{data=await api('admin/stock?companyId='+encodeURIComponent($('[name=companyId]').value));$('[name=stockSearch]').value='';drawLots()}catch(e){$('#formError').textContent=e.message}};syncLot();
 },
