 const sync=()=>{const it=item($('[name=itemId]').value),unit=$('[name=inputUnit]'),previous=unit.value,choices=it?purchaseUnits(it):[];unit.innerHTML=choices.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>').join('');unit.value=choices.some(x=>x.id===previous)?previous:(it?.presentationName?'presentation':it?.unit||'');if(op==='purchase'){const linked=it?.supplierIds??(it?.supplierId?[it.supplierId]:[]),ss=options('suppliers'),preferred=ss.filter(s=>linked.includes(s.id)),suggested=preferred.length===1?preferred[0].id:'',supplier=$('[name=supplierId]');supplier.innerHTML='<option value="">Seleccionar…</option>'+ss.map(s=>'<option value="'+esc(s.id)+'">'+esc(s.name)+'</option>').join('');supplier.value=suggested;$('#supplierWarning').hidden=true}preview()};
