function addSaleLine(){const row=document.createElement('section');row.className='sale-line panel';const products=options('items').filter(x=>x.kind==='product');row.innerHTML='<div class="line-head"><h3>Producto a despachar</h3><button type="button" class="secondary remove-line">Quitar</button></div>'+select('itemId','Producto terminado',products)+select('priceType','Lista de precios',[{id:'retail',name:'Minorista'},{id:'wholesale',name:'Mayorista'}],'retail',false)+field('discountPercent','Descuento adicional (%)','number',0,'min="0" max="100" step="0.01" required')+field('unitPrice','Precio unitario antes del descuento','number',0,'min="0" step="any" required')+field('desiredQty','Cantidad a vender','number','','min="0.000001" step="any"')+'<div class="full"><button type="button" class="secondary modify-line-lots">Modificar lotes</button><p class="suggest-note" role="status">Al indicar producto y cantidad, se asignan automáticamente los lotes más antiguos.</p></div><div class="line-lots full"></div>';let suggestTimer;const refreshLots=()=>{const product=row.querySelector('[name=itemId]').value;row.querySelector('.line-lots').innerHTML=lotInputs([product]);setPrice();updateSaleTotal()};const setPrice=()=>{const it=item(row.querySelector('[name=itemId]').value),type=row.querySelector('[name=priceType]').value;row.querySelector('[name=unitPrice]').value=(type==='wholesale'?it?.wholesalePrice:it?.salePrice)||0;updateSaleTotal()};const suggest=async()=>{const product=row.querySelector('[name=itemId]').value,qty=row.querySelector('[name=desiredQty]').value;if(!product||Number(qty)<=0){row.querySelector('.suggest-note').textContent='Indicá producto y cantidad para asignar los lotes automáticamente.';return}try{const result=await api('suggest?item='+encodeURIComponent(product)+'&qty='+encodeURIComponent(qty)+'&date='+encodeURIComponent($('[name=date]').value));row.querySelectorAll('[data-lot]').forEach(input=>input.value=result.allocations.find(x=>x.lotId===input.dataset.lot)?.qty||0);const missing=result.shortages.map(x=>name('items',x.itemId)+' ('+num(x.qty)+' '+item(x.itemId).unit+')');row.querySelector('.suggest-note').textContent=missing.length?'No alcanza el stock disponible: '+missing.join(', '):'Lotes más antiguos asignados automáticamente. Usá “Modificar lotes” solo si necesitás una excepción.';updateSaleTotal()}catch(e){row.querySelector('.suggest-note').textContent=e.message}};const scheduleSuggestion=()=>{clearTimeout(suggestTimer);suggestTimer=setTimeout(suggest,250)};row.querySelector('[name=itemId]').onchange=()=>{refreshLots();scheduleSuggestion()};row.querySelector('[name=priceType]').onchange=setPrice;row.querySelector('[name=desiredQty]').oninput=scheduleSuggestion;row.querySelector('.remove-line').onclick=()=>{if($$('.sale-line').length===1){message('La venta debe incluir al menos un producto.');return}row.remove();updateSaleTotal()};row.querySelector('.modify-line-lots').onclick=()=>{clearTimeout(suggestTimer);row.querySelectorAll('[data-lot]').forEach(input=>input.readOnly=false);row.querySelector('.suggest-note').textContent='Edición manual habilitada solo para este producto.'};row.oninput=updateSaleTotal;$('#saleLines').append(row);refreshLots()}
function updateSaleTotal(){const lines=$$('.sale-line');if(!lines.length)return;let total=0,qty=0;for(const row of lines){const lineQty=[...row.querySelectorAll('[data-lot]')].reduce((sum,input)=>sum+Number(input.value||0),0),base=Number(row.querySelector('[name=unitPrice]').value||0),discount=Number(row.querySelector('[name=discountPercent]').value||0),net=Math.round(base*(1-discount/100)*100)/100;qty+=lineQty;total+=lineQty*net}$('#saleTotal').textContent='Productos: '+lines.length+' · Cantidad total: '+num(qty)+' · Total: '+money(total)}
