async function readAttachments(){const docs=[];let total=0;for(const input of $$('[data-document]')){const file=input.files?.[0];if(!file)continue;total+=file.size;if(total>5*1024*1024)throw Error('Los PDFs seleccionados superan los 5 MB por guardado.');if(!file.name.toLowerCase().endsWith('.pdf'))throw Error('Seleccioná un PDF.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve('data:application/pdf;base64,'+String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('No se pudo leer el PDF.'));reader.readAsDataURL(file)});docs.push({label:input.dataset.document,name:file.name,data})}return docs}
