async function exportScreenPDF(){if(!window.PDFLib)throw Error('No se pudo cargar el generador PDF. Recargá la página.');const {PDFDocument,StandardFonts,rgb}=window.PDFLib,pdf=await PDFDocument.create(),font=await pdf.embedFont(StandardFonts.Helvetica);let page,y;const safe=s=>String(s).replace(/[^\x20-\x7e\xa0-\xff\n]/g,' ');function fresh(){page=pdf.addPage([842,595]);y=560}function line(text,size=10){const words=safe(text).split(/\s+/);let current='';for(const word of words){for(const chunk of word.match(/.{1,100}/g)||[]){const next=current?current+' '+chunk:chunk;if(font.widthOfTextAtSize(next,size)>755&&current){put(current,size);current=chunk}else current=next}}if(current)put(current,size)}function put(text,size){if(y<40)fresh();page.drawText(text,{x:40,y,size,font,color:rgb(.1,.2,.15)});y-=size+6}fresh();line('Consultora en Alimentos',14);line(state.deliverySettings?.businessName||state.company,16);line(labels[view]+' · '+(view==='lots'?'Stock actual al '+today():month),12);
 const root=$('#reportResult')||$('#traceResult')||$('#content');for(const element of root.querySelectorAll('h2,h3,p,table,.card,.document-group')){if(element.closest('.toolbar,.report-controls'))continue;if(element.tagName==='TABLE'){const heads=[...element.querySelectorAll('thead th')].map(x=>x.textContent);for(const tr of element.querySelectorAll('tbody tr')){const cells=[...tr.children].map(x=>{const copy=x.cloneNode(true);copy.querySelectorAll('button').forEach(b=>b.remove());return copy.textContent.trim()});line(cells.map((v,i)=>v?heads[i]+': '+v:'').filter(Boolean).join(' | '));y-=5}}else line(element.textContent,element.tagName.startsWith('H')?12:10)}
 download(new Blob([await pdf.save()],{type:'application/pdf'}),view+'-'+today()+'.pdf','application/pdf');message('PDF generado y descargado. Podés abrirlo para imprimir.');
}

